19	/// Stores feature flags that control collaboration-mode behavior.
20	///
21	/// Keep mode-related flags here so new collaboration-mode capabilities can be
22	/// added without large cross-cutting diffs to constructor and call-site
23	/// signatures.
24	#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
25	pub struct CollaborationModesConfig {
26	    /// Enables `request_user_input` availability in Default mode.
27	    pub default_mode_request_user_input: bool,
28	}
29	
30	pub fn builtin_collaboration_mode_presets(
31	    collaboration_modes_config: CollaborationModesConfig,
32	) -> Vec<CollaborationModeMask> {
33	    vec![plan_preset(), default_preset(collaboration_modes_config)]
34	}
35	
36	fn plan_preset() -> CollaborationModeMask {
37	    CollaborationModeMask {
38	        name: ModeKind::Plan.display_name().to_string(),
39	        mode: Some(ModeKind::Plan),
40	        model: None,
41	        reasoning_effort: Some(Some(ReasoningEffort::Medium)),
42	        developer_instructions: Some(Some(COLLABORATION_MODE_PLAN.to_string())),
43	    }
44	}
45	
46	fn default_preset(collaboration_modes_config: CollaborationModesConfig) -> CollaborationModeMask {
47	    CollaborationModeMask {
48	        name: ModeKind::Default.display_name().to_string(),
49	        mode: Some(ModeKind::Default),
50	        model: None,
51	        reasoning_effort: None,
52	        developer_instructions: Some(Some(default_mode_instructions(collaboration_modes_config))),
53	    }
54	}
55	
56	fn default_mode_instructions(collaboration_modes_config: CollaborationModesConfig) -> String {
57	    let known_mode_names = format_mode_names(&TUI_VISIBLE_COLLABORATION_MODES);
58	    let request_user_input_availability = request_user_input_availability_message(
59	        ModeKind::Default,
60	        collaboration_modes_config.default_mode_request_user_input,
61	    );
62	    let asking_questions_guidance = asking_questions_guidance_message(
63	        collaboration_modes_config.default_mode_request_user_input,
64	    );
65	    COLLABORATION_MODE_DEFAULT_TEMPLATE
66	        .render([
67	            (KNOWN_MODE_NAMES_TEMPLATE_KEY, known_mode_names.as_str()),
68	            (
69	                REQUEST_USER_INPUT_AVAILABILITY_TEMPLATE_KEY,
70	                request_user_input_availability.as_str(),
71	            ),
72	            (
73	                ASKING_QUESTIONS_GUIDANCE_TEMPLATE_KEY,
74	                asking_questions_guidance.as_str(),
75	            ),
76	        ])
77	        .unwrap_or_else(|err| panic!("collaboration mode default template must render: {err}"))
78	}
79	
80	fn format_mode_names(modes: &[ModeKind]) -> String {
81	    let mode_names: Vec<&str> = modes.iter().map(|mode| mode.display_name()).collect();
82	    match mode_names.as_slice() {
83	        [] => "none".to_string(),
84	        [mode_name] => (*mode_name).to_string(),
85	        [first, second] => format!("{first} and {second}"),
86	        [..] => mode_names.join(", "),
87	    }
88	}
89	
90	fn request_user_input_availability_message(
91	    mode: ModeKind,
92	    default_mode_request_user_input: bool,
93	) -> String {
94	    let mode_name = mode.display_name();
95	    if mode.allows_request_user_input()
96	        || (default_mode_request_user_input && mode == ModeKind::Default)
97	    {
98	        format!("The `request_user_input` tool is available in {mode_name} mode.")
99	    } else {
100	        format!(
101	            "The `request_user_input` tool is unavailable in {mode_name} mode. If you call it while in {mode_name} mode, it will return an error."
102	        )
103	    }
104	}
105	
106	fn asking_questions_guidance_message(default_mode_request_user_input: bool) -> String {
107	    if default_mode_request_user_input {
108	        "In Default mode, strongly prefer making reasonable assumptions and executing the user's request rather than stopping to ask questions. If you absolutely must ask a question because the answer cannot be discovered from local context and a reasonable assumption would be risky, prefer using the `request_user_input` tool rather than writing a multiple choice question as a textual assistant message. Never write a multiple choice question as a textual assistant message.".to_string()
109	    } else {
110	        "In Default mode, strongly prefer making reasonable assumptions and executing the user's request rather than stopping to ask questions. If you absolutely must ask a question because the answer cannot be discovered from local context and a reasonable assumption would be risky, ask the user directly with a concise plain-text question. Never write a multiple choice question as a textual assistant message.".to_string()
111	    }
112	}
